def validate(v,s,path='study'):
 t=s.get('type'); check={'object':lambda:isinstance(v,dict),'array':lambda:isinstance(v,list),'string':lambda:isinstance(v,str),'boolean':lambda:isinstance(v,bool),'integer':lambda:isinstance(v,int) and not isinstance(v,bool),'number':lambda:isinstance(v,(int,float)) and not isinstance(v,bool)}
 if t: assert check[t](),(path,t)
 if 'enum' in s: assert v in s['enum'],path
 if 'const' in s: assert v==s['const'],path
 if isinstance(v,dict):
  assert all(k in v for k in s.get('required',[])),path
  if s.get('additionalProperties') is False: assert not (v.keys()-s.get('properties',{}).keys()),path
  for k,x in v.items():
   if k in s.get('properties',{}): validate(x,s['properties'][k],path+'.'+k)
 if isinstance(v,list):
  assert len(v)>=s.get('minItems',0),path
  for i,x in enumerate(v): validate(x,s.get('items',{}),path+f'[{i}]')
 if isinstance(v,str): assert len(v)>=s.get('minLength',0),path
